def transform(grid):
    # Locate each T component, classify stem orientation, then render its marker.
    h,w=len(grid),len(grid[0]); seen=set(); objs=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=2 or (r,c) in seen: continue
            todo=[(r,c)]; seen.add((r,c)); pts=[]
            while todo:
                y,x=todo.pop(); pts.append((y,x))
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        p=(y+dy,x+dx)
                        if 0<=p[0]<h and 0<=p[1]<w and grid[p[0]][p[1]]==2 and p not in seen:
                            seen.add(p); todo.append(p)
            a=min(y for y,x in pts); b=min(x for y,x in pts)
            z={(y-a,x-b) for y,x in pts}
            hh=max(y for y,x in pts)-a+1; ww=max(x for y,x in pts)-b+1
            if hh==2: ori='down' if (1,1) in z else 'up'
            else: ori='right' if (1,1) in z else 'left'
            objs.append((a,b,ori))
    objs.sort()
    # T's stem points toward the marker: up/left map to 3, down/right map to 1.
    out=[[0]*6 for _ in range(3)]
    for i,(r,c,o) in enumerate(objs):
        rr=0 if i<3 else 2
        cc=i%3
        val=3 if o in ('up','left') else 1
        out[rr][2*cc]=val
    return out

